using namespace std;

class SuffixTree {
private:
    struct Node {
        int start;
        int end;
        Node* suffixLink;
        unordered_map<char, Node*> children;

        Node(int start, int end) {
            this->start = start;
            this->end = end;
            suffixLink = nullptr;
        }

        int getLength() {
            return min(end, (int)text.size()) - start;
        }

        string getText() {
            return text.substr(start, getLength());
        }

        void addChild(Node* node) {
            char c = text[node->start];
            children[c] = node;
        }
    };

    Node* root;
    Node* activeNode;
    int activeEdge;
    int activeLength;
    int remaining;

    string text;

public:
    SuffixTree(string text) {
        this->text = text;
        root = new Node(-1, -1);
        activeNode = root;
        activeEdge = -1;
        activeLength = 0;
        remaining = 0;
        build();
    }

    void print() {
        printHelper(root, 0);
    }

private:
    Node* split(Node* node) {
        if (activeLength == 0) {
            return node;
        }

        char startChar = text[node->start + activeEdge];
        Node* child = node->children[startChar];
        int splitEnd = node->start + activeEdge + activeLength - 1;

        if (child->getLength() == activeLength) {
            return child;
        }

        Node* splitNode = new Node(child->start, child->start + activeLength);
        node->addChild(splitNode);
        child->start += activeLength;
        splitNode->addChild(child);
        return splitNode;
    }

    void extend(int index) {
        remaining++;
        Node* lastNode = nullptr;

        while (remaining > 0) {
            if (activeLength == 0) {
                activeEdge = index;
            }

            char nextChar = text[index];
            if (activeNode->children[nextChar] == nullptr) {
                Node* newNode = new Node(index, text.size());
                activeNode->addChild(newNode);
                if (lastNode != nullptr) {
                    lastNode->suffixLink = activeNode;
                }
                lastNode = activeNode;
            } else {
                Node* nextNode = activeNode->children[nextChar];
                if (walkDown(nextNode)) {
                    continue;
                }

                char nextChar2 = text[nextNode->start + activeLength];
                if (nextChar == nextChar2) {
                    activeLength++;
                    if (lastNode != nullptr) {
                        lastNode->suffixLink = activeNode;
                    }
                    break;
                }

                Node* splitNode = split(nextNode);
                Node* newNode = new Node(index, text.size());
                activeNode->addChild(splitNode);
                newNode->addChild(splitNode);
                activeNode->addChild(newNode);
                if (lastNode != nullptr) {
                    lastNode->suffixLink = newNode;
                }
                lastNode = newNode;
            }

            remaining--;
            if (activeNode == root && activeLength > 0) {
                activeLength--;
                activeEdge = index - remaining + 1;
            } else {
                activeNode = activeNode->suffixLink != nullptr ? activeNode->suffixLink : root;
            }
        }
    }

    bool walkDown(Node* node) {
        int length = node->getLength();
        if (activeLength >= length) {
            activeEdge += length;
            activeLength -= length;
            activeNode = node;
            return true;
        }
        return false;
    }

    void build() {
        for (int i = 0; i < text.size(); i++) {
            extend(i);
        }
    }

    void printHelper(Node* node, int level) {
        cout << string(level * 2, ' ') << node->getText() << endl;
        for (auto child : node->children) {
            printHelper(child.second, level + 1);
        }
    }
};

